const puppeteer = require('puppeteer');

(async () => {
  const url = process.argv[2] || 'http://localhost:5174/';
  console.log('Checking', url);
  const browser = await puppeteer.launch({ args: ['--no-sandbox','--disable-setuid-sandbox'] });
  const page = await browser.newPage();

  page.on('console', msg => {
    const args = msg.args();
    Promise.all(args.map(a => a.jsonValue())).then(vals => {
      console.log('PAGE LOG:', msg.type(), ...vals);
    }).catch(() => {
      console.log('PAGE LOG:', msg.type(), msg.text());
    });
  });

  page.on('pageerror', err => console.log('PAGE ERROR:', err && err.toString()));

  try {
    await page.goto(url, { waitUntil: 'networkidle2', timeout: 10000 });
    // wait a little to capture runtime console messages
    await page.waitForTimeout(1500);
  } catch (e) {
    console.error('Puppeteer error', e && e.toString());
  }

  await browser.close();
  process.exit(0);
})();

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = process.env.PORT ? parseInt(process.env.PORT, 10) : 5174;
const ROOT = path.join(process.cwd(), 'dist');

function contentType(file) {
  const ext = path.extname(file).toLowerCase();
  switch (ext) {
    case '.html': return 'text/html; charset=utf-8';
    case '.js': return 'application/javascript; charset=utf-8';
    case '.css': return 'text/css; charset=utf-8';
    case '.png': return 'image/png';
    case '.jpg': case '.jpeg': return 'image/jpeg';
    case '.wasm': return 'application/wasm';
    case '.json': return 'application/json; charset=utf-8';
    default: return 'application/octet-stream';
  }
}

const server = http.createServer((req, res) => {
  let urlPath = decodeURIComponent(req.url.split('?')[0]);
  if (urlPath === '/') urlPath = '/index.html';
  const filePath = path.join(ROOT, urlPath);
  fs.stat(filePath, (err, st) => {
    if (err || !st.isFile()) {
      res.statusCode = 404; res.end('Not found'); return;
    }
    res.setHeader('Content-Type', contentType(filePath));
    fs.createReadStream(filePath).pipe(res);
  });
});

server.listen(PORT, () => {
  console.log(`Serving dist at http://localhost:${PORT}`);
});

process.on('SIGINT', () => {
  server.close(() => process.exit(0));
});

