fn is_position_clear(x: f32, y: f32, radius: f32) -> bool {
    // Simpler collision: test center and 4 cardinal directions only
    // This is less strict and allows better corner navigation
    if map_at(x as i32, y as i32) != 0 {
        return false;
    }

    // Test 4 cardinal points on circle perimeter (N, E, S, W)
    let test_points = [
        (x + radius, y),          // East
        (x - radius, y),          // West
        (x, y + radius),          // South
        (x, y - radius),          // North
    ];

    for &(test_x, test_y) in &test_points {
        if map_at(test_x as i32, test_y as i32) != 0 {
            return false;
        }
    }
    true
}

// Wall sliding helper: projects movement onto wall normal when collision occurs
fn slide_move(start_x: f32, start_y: f32, dx: f32, dy: f32, radius: f32) -> (f32, f32) {
    let target_x = start_x + dx;
    let target_y = start_y + dy;

    // Try full movement first
    if is_position_clear(target_x, target_y, radius) {
        return (target_x, target_y);
    }

    // Try X-only movement (sliding along Y wall)
    if is_position_clear(target_x, start_y, radius) {
        return (target_x, start_y);
    }

    // Try Y-only movement (sliding along X wall)
    if is_position_clear(start_x, target_y, radius) {
        return (start_x, target_y);
    }

    // Stuck at corner - try very small movements to escape
    // Test tiny steps in both directions
    let tiny_fractions = [0.3, 0.15, 0.05];
    for &frac in &tiny_fractions {
        let tiny_x = start_x + dx * frac;
        let tiny_y = start_y + dy * frac;

        // Try tiny diagonal first
        if is_position_clear(tiny_x, tiny_y, radius) {
            return (tiny_x, tiny_y);
        }
        // Try tiny X only
        if is_position_clear(tiny_x, start_y, radius) {
            return (tiny_x, start_y);
        }
        // Try tiny Y only
        if is_position_clear(start_x, tiny_y, radius) {
            return (start_x, tiny_y);
        }
    }

    // Completely stuck - don't move
    (start_x, start_y)
}

