// Classic Wolfenstein 3D / Doom style collision with wall sliding.
// The key insight: when approaching a corner, slide along the wall where
// the movement component is larger. No push-back, no escape vectors.
// This creates smooth, predictable movement that never gets stuck.
fn slide_move(start_x: f32, start_y: f32, dx: f32, dy: f32, radius: f32) -> (f32, f32) {
    // Calculate target position
    let target_x = start_x + dx;
    let target_y = start_y + dy;

    // 1. Try full diagonal movement first
    if is_position_clear(target_x, target_y, radius) {
        return (target_x, target_y);
    }

    // 2. Movement is blocked. Try sliding along each axis independently.
    //    The classic approach: try moving along each axis separately,
    //    prioritizing the axis with larger movement component.

    let abs_dx = dx.abs();
    let abs_dy = dy.abs();

    // Try the axis with larger movement first (more natural sliding)
    if abs_dx >= abs_dy {
        // Try X movement first, then Y
        if abs_dx > 0.0001 && is_position_clear(target_x, start_y, radius) {
            return (target_x, start_y);
        }
        if abs_dy > 0.0001 && is_position_clear(start_x, target_y, radius) {
            return (start_x, target_y);
        }
    } else {
        // Try Y movement first, then X
        if abs_dy > 0.0001 && is_position_clear(start_x, target_y, radius) {
            return (start_x, target_y);
        }
        if abs_dx > 0.0001 && is_position_clear(target_x, start_y, radius) {
            return (target_x, start_y);
        }
    }

    // 3. Both axes blocked at full movement. This happens at corners.
    //    Try partial movement along each axis to find a valid slide.
    //    This allows sliding along a wall when very close to a corner.

    // Find how far we can move along X axis
    let mut best_x = start_x;
    if abs_dx > 0.0001 {
        // Binary search for maximum valid X movement
        let mut lo = 0.0_f32;
        let mut hi = 1.0_f32;
        for _ in 0..8 {
            let mid = (lo + hi) * 0.5;
            let test_x = start_x + dx * mid;
            if is_position_clear(test_x, start_y, radius) {
                lo = mid;
                best_x = test_x;
            } else {
                hi = mid;
            }
        }
    }

    // Find how far we can move along Y axis
    let mut best_y = start_y;
    if abs_dy > 0.0001 {
        let mut lo = 0.0_f32;
        let mut hi = 1.0_f32;
        for _ in 0..8 {
            let mid = (lo + hi) * 0.5;
            let test_y = start_y + dy * mid;
            if is_position_clear(start_x, test_y, radius) {
                lo = mid;
                best_y = test_y;
            } else {
                hi = mid;
            }
        }
    }

    // Calculate how much movement we got on each axis
    let moved_x = (best_x - start_x).abs();
    let moved_y = (best_y - start_y).abs();

    // Return the axis that allowed more movement (smooth corner sliding)
    if moved_x > 0.0001 || moved_y > 0.0001 {
        if moved_x >= moved_y {
            return (best_x, start_y);
        } else {
            return (start_x, best_y);
